      var model=el('div'); model.hidden=true; model.style.cssText='background:#E8F5E9;border-radius:10px;padding:12px;margin:10px 0;';
      model.appendChild(el('strong','نموذج الإجابة:')); model.appendChild(el('p',question.answerModel || question.answerText)); model.appendChild(el('strong','توزيع الدرجات:'));
      var list=el('ul'); (question.rubric || []).forEach(function(row){ list.appendChild(el('li',row.criterion+' ('+row.points+' درجات)')); }); model.appendChild(list);
      var reveal=el('button','إظهار نموذج الإجابة ومعايير التقييم'); reveal.type='button'; reveal.style.cssText='margin:8px 6px 8px 0;padding:9px 12px;border:0;border-radius:8px;background:#1976D2;color:#fff;font:inherit;cursor:pointer;'; reveal.addEventListener('click',function(){model.hidden=!model.hidden; reveal.textContent=model.hidden?'إظهار نموذج الإجابة وتوزيع الدرجات':'إخفاء نموذج الإجابة';}); block.appendChild(reveal);
      var score=el('input'); score.type='number'; score.min='0'; score.max=String(question.points); score.step='0.5'; score.placeholder='درجتك من '+question.points; score.setAttribute('aria-label','درجتك بعد المراجعة'); score.style.cssText='width:150px;max-width:45%;padding:8px;border:1px solid #90a4ae;border-radius:8px;font:inherit;'; block.appendChild(score);
      var save=el('button','حفظ درجتي'); save.type='button'; save.style.cssText='margin:8px;padding:9px 12px;border:0;border-radius:8px;background:#2E7D32;color:#fff;font:inherit;cursor:pointer;';
      var msg=el('span'); msg.setAttribute('aria-live','polite');
      save.addEventListener('click',function(){ var n=Number(score.value); if(score.value==='' || !isFinite(n) || n<0 || n>question.points){msg.textContent=' أدخل درجة من 0 إلى '+question.points+'.';msg.style.color='#B71C1C';return;}
        var scores=readScores(); scores[courseKey+'|'+(pathKey||'')+'|'+question.id]={courseKey:courseKey,pathKey:pathKey||'',itemTitle:itemTitle,question:question.q,score:n,points:question.points,sourceId:sourceId,updatedAt:new Date().toISOString()};
        var saved=writeScores(scores); msg.textContent=saved?' تم حفظ التقييم على هذا الجهاز.':' تعذر حفظ الدرجة في هذا المتصفح.';msg.style.color=saved?'#1B5E20':'#B71C1C';
      });
      block.appendChild(save); block.appendChild(msg); block.appendChild(model); wrap.appendChild(block);
