      body.appendChild(el('p',found.item.note||'أجب أولاً، ثم راجع التعليل ونموذج الإجابة.'));
      if(found.kind==='exercise')body.appendChild(el('h3',found.unit.title));
      body.appendChild(questionsBox(questions,found.item.id));
      if(written.length){body.appendChild(el('h3','أسئلة مقالية وتعبيرية — نموذج إجابة وتوزيع درجات'));body.appendChild(essayBox(written,found.item.id,found.courseKey,found.pathKey,found.item.title));}
